_STATUS_SMOKE_AUTH_TOKEN = "status-smoke-auth-token-32-chars-minimum"
_STATUS_SMOKE_AUTH_HEADER = "Basic " + base64.b64encode(
    f"jarvis:{_STATUS_SMOKE_AUTH_TOKEN}".encode("utf-8")
).decode("ascii")


def _read_json(url: str) -> dict:
    with urllib.request.urlopen(url, timeout=5) as response:
        return json.loads(response.read().decode("utf-8"))


def _read_text(url: str) -> str:
    with urllib.request.urlopen(url, timeout=5) as response:
        return response.read().decode("utf-8")


def _read_json_allowing_error(url: str) -> tuple[int, dict]:
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            status = getattr(response, "status", None)
            if status is None:
                status = response.getcode() if hasattr(response, "getcode") else 200
            return int(status), json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        return exc.code, json.loads(exc.read().decode("utf-8"))


def _raw_in_process_status_response(
    runtime,
    request: bytes,
    *,
    auth_token: str = _STATUS_SMOKE_AUTH_TOKEN,
) -> tuple[int, dict[str, str], bytes]:
    class InProcessSocket:
        def __init__(self) -> None:
            self.request = BytesIO(request)
            self.response = BytesIO()

        def makefile(self, mode: str, *args, **kwargs) -> BytesIO:
            return self.request if "r" in mode else self.response

        def sendall(self, data: bytes) -> None:
            self.response.write(data)

        def close(self) -> None:
            return

    class InProcessServer:
        server_address = ("127.0.0.1", 0)
        server_name = "127.0.0.1"
        server_port = 0

    class BoundStatusHandler(status_server.StatusHandler):
        pass

    BoundStatusHandler.runtime = runtime
    BoundStatusHandler.auth_token = auth_token
    sock = InProcessSocket()
    BoundStatusHandler(sock, ("127.0.0.1", 0), InProcessServer())
    raw = sock.response.getvalue()
    raw_headers, separator, body = raw.partition(b"\r\n\r\n")
    if not separator:
        raise SystemExit(f"Status boundary smoke received malformed HTTP response: {raw[:200]!r}")
    lines = raw_headers.decode("iso-8859-1").split("\r\n")
    status_parts = lines[0].split(" ", 2)
    status = int(status_parts[1])
    headers: dict[str, str] = {}
    for line in lines[1:]:
        name, _, value = line.partition(":")
        headers[name.strip().lower()] = value.strip()
    return status, headers, body


def _assert_status_request_boundary_hardening() -> None:
    constructor_calls: list[tuple] = []
    warmup_calls: list[bool] = []
    original_http_server = status_server.ThreadingHTTPServer
    original_warmup = status_server._start_dashboard_voice_warmup
    try:
        status_server.ThreadingHTTPServer = lambda *args, **kwargs: constructor_calls.append(  # type: ignore[assignment]
            (args, kwargs)
        )
        status_server._start_dashboard_voice_warmup = lambda: warmup_calls.append(True)  # type: ignore[assignment]
        for host, token in [
            ("0.0.0.0", _STATUS_SMOKE_AUTH_TOKEN),
            ("127.0.0.1", "too-short"),
        ]:
            try:
                status_server.make_status_server(object(), host, 8765, auth_token=token)
            except ValueError:
                pass
            else:
                raise SystemExit("Status server accepted an unsafe host or authentication token.")
    finally:
        status_server.ThreadingHTTPServer = original_http_server  # type: ignore[assignment]
        status_server._start_dashboard_voice_warmup = original_warmup  # type: ignore[assignment]
    if constructor_calls or warmup_calls:
        raise SystemExit("Status server validated its security boundary after construction or warmup.")

    class FakeBoundServer:
        forced_host: str | None = None
        instances: list["FakeBoundServer"] = []

        def __init__(self, address, handler_cls) -> None:
            host, port = address
            self.server_address = (self.forced_host or host, port)
            self.handler_cls = handler_cls
            self.closed = False
            self.instances.append(self)

        def server_close(self) -> None:
            self.closed = True

    original_http_server = status_server.ThreadingHTTPServer
    original_warmup = status_server._start_dashboard_voice_warmup
    warmup_calls = []
    try:
        status_server.ThreadingHTTPServer = FakeBoundServer  # type: ignore[assignment]
        status_server._start_dashboard_voice_warmup = lambda: warmup_calls.append(True)  # type: ignore[assignment]
        FakeBoundServer.forced_host = "192.168.1.20"
        try:
            status_server.make_status_server(
                object(),
                "localhost",
                8765,
                auth_token=_STATUS_SMOKE_AUTH_TOKEN,
            )
        except ValueError:
            pass
        else:
            raise SystemExit("Status server trusted a loopback hostname that resolved non-loopback.")
        if not FakeBoundServer.instances[-1].closed or warmup_calls:
            raise SystemExit("Status server did not close a non-loopback resolved bind before warmup.")

        FakeBoundServer.forced_host = None
        ipv6_server = status_server.make_status_server(
            object(),
            "::1",
            8765,
            auth_token=_STATUS_SMOKE_AUTH_TOKEN,
        )
        if getattr(type(ipv6_server), "address_family", None) != status_server.socket.AF_INET6:
            raise SystemExit("Status server did not select an IPv6 server for ::1.")
        if "::1" not in getattr(ipv6_server.handler_cls, "allowed_authority_hosts", frozenset()):
            raise SystemExit("Status server did not bind the IPv6 loopback authority explicitly.")
    finally:
        status_server.ThreadingHTTPServer = original_http_server  # type: ignore[assignment]
        status_server._start_dashboard_voice_warmup = original_warmup  # type: ignore[assignment]
        FakeBoundServer.forced_host = None

    with TemporaryDirectory(prefix="jarvis-status-boundary-") as temp:
        runtime = make_temp_runtime(Path(temp))

        status, headers, body = _raw_in_process_status_response(
            runtime,
            (
                "GET / HTTP/1.1\r\n"
                "Host: inprocess.local\r\n"
                f"Authorization: {_STATUS_SMOKE_AUTH_HEADER}\r\n\r\n"
            ).encode("utf-8"),
        )
        if status != 200:
            raise SystemExit(f"Status dashboard valid local request was rejected: {status}, {body[:200]!r}")
        required_headers = {
            "cache-control": "no-store",
            "cross-origin-resource-policy": "same-origin",
            "referrer-policy": "no-referrer",
            "x-content-type-options": "nosniff",
            "x-frame-options": "DENY",
        }
        for name, expected in required_headers.items():
            if headers.get(name) != expected:
                raise SystemExit(f"Status dashboard security header {name!r} was {headers.get(name)!r}")
        html = body.decode("utf-8")
        nonce_match = re.search(r'<script nonce="([^"]+)">', html)
        if nonce_match is None or "<script>" in html:
            raise SystemExit("Status dashboard HTML did not nonce every inline script block.")
        csp = headers.get("content-security-policy", "")
        if f"script-src 'nonce-{nonce_match.group(1)}'" not in csp:
            raise SystemExit(f"Status dashboard CSP was not bound to the rendered script nonce: {csp!r}")
        for expected in ["default-src 'none'", "frame-ancestors 'none'", "object-src 'none'"]:
            if expected not in csp:
                raise SystemExit(f"Status dashboard CSP missed {expected!r}: {csp!r}")

        status, headers, body = _raw_in_process_status_response(
            runtime,
            b"GET /api/status HTTP/1.1\r\nHost: hostile.example\r\n\r\n",
        )
        rejected = json.loads(body.decode("utf-8"))
        if status != 421 or rejected.get("error") != "status_dashboard_host_rejected":
            raise SystemExit(f"Status dashboard did not reject a hostile Host header: {status}, {rejected}")
        if headers.get("cache-control") != "no-store":
            raise SystemExit("Status dashboard Host rejection missed response security headers.")

        auth_approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        auth_runs_before = len(runtime.store.recent_tool_runs(limit=100))
        status, headers, body = _raw_in_process_status_response(
            runtime,
            b"GET /api/status HTTP/1.1\r\nHost: inprocess.local\r\n\r\n",
        )
        rejected = json.loads(body.decode("utf-8"))
        expected_auth_rejection = {
            "ok": False,
            "error": "status_dashboard_authentication_required",
            "safety": "Dashboard authentication is required before endpoint handling.",
            "recovery": status_server._STATUS_AUTH_RECOVERY_GUIDANCE,
        }
        if status != 401 or rejected.get("error") != "status_dashboard_authentication_required":
            raise SystemExit(f"Status dashboard did not reject missing authentication: {status}, {rejected}")
        if rejected != expected_auth_rejection:
            raise SystemExit(
                f"Status dashboard authentication rejection missed bounded recovery: {rejected}"
            )
        generic_auth_body = body
        if not headers.get("www-authenticate", "").startswith('Basic realm="Jarvis Status"'):
            raise SystemExit("Status dashboard authentication rejection missed its Basic challenge.")
        if headers.get("cache-control") != "no-store":
            raise SystemExit("Status dashboard authentication rejection missed response security headers.")

        rejected_credentials = {
            "wrong password": "Basic "
            + base64.b64encode(b"jarvis:wrong-status-smoke-auth-token-32-chars").decode("ascii"),
            "wrong username": "Basic "
            + base64.b64encode(f"someone:{_STATUS_SMOKE_AUTH_TOKEN}".encode("utf-8")).decode("ascii"),
            "bearer scheme": "Bearer opaque",
            "invalid base64": "Basic !!!not-base64!!!",
            "non-utf8": "Basic " + base64.b64encode(b"\xff\xfe").decode("ascii"),
            "missing colon": "Basic " + base64.b64encode(b"jarvis").decode("ascii"),
            "empty password": "Basic " + base64.b64encode(b"jarvis:").decode("ascii"),
        }
        for label, auth_header in rejected_credentials.items():
            status, response_headers, body = _raw_in_process_status_response(
                runtime,
                (
                    "POST /api/dashboard-stop-speech HTTP/1.1\r\n"
                    "Host: inprocess.local\r\n"
                    f"Authorization: {auth_header}\r\n"
                    "Content-Type: application/json\r\n"
                    "Content-Length: 10\r\n\r\n"
                    "not-json!!"
                ).encode("utf-8"),
            )
            rejected = json.loads(body.decode("utf-8"))
            response_text = repr((status, response_headers, body))
            if status != 401 or rejected.get("error") != "status_dashboard_authentication_required":
                raise SystemExit(
                    f"Status dashboard did not reject {label} before reading a bad body: "
                    f"{status}, {rejected}"
                )
            if rejected != expected_auth_rejection or body != generic_auth_body:
                raise SystemExit(
                    f"Status dashboard distinguished the {label} credential error or changed recovery guidance."
                )
            for secret_fragment in (_STATUS_SMOKE_AUTH_TOKEN, "wrong-status-smoke-auth-token"):
                if secret_fragment in response_text:
                    raise SystemExit(f"Status dashboard {label} rejection leaked credential material.")
            for forbidden_header_fragment in ("Authorization", auth_header):
                if forbidden_header_fragment in response_text:
                    raise SystemExit(
                        f"Status dashboard {label} rejection echoed authentication headers."
                    )
        if len(runtime.store.list_pending_approvals(limit=100)) != auth_approvals_before:
            raise SystemExit("Status dashboard authentication rejection queued an approval.")
        if len(runtime.store.recent_tool_runs(limit=100)) != auth_runs_before:
            raise SystemExit("Status dashboard authentication rejection logged a tool execution.")

        colon_token = "status:smoke:auth:token:32:chars:minimum"
        colon_header = "Basic " + base64.b64encode(f"jarvis:{colon_token}".encode("utf-8")).decode("ascii")
        status, _, _ = _raw_in_process_status_response(
            runtime,
            (
                "GET /api/status HTTP/1.1\r\n"
                "Host: inprocess.local\r\n"
                f"Authorization: {colon_header}\r\n\r\n"
            ).encode("utf-8"),
            auth_token=colon_token,
        )
        if status != 200:
            raise SystemExit("Status dashboard rejected a valid authentication token containing colons.")

        for boundary_header, expected_error in [
            ("Origin: http://hostile.example\r\n", "status_dashboard_origin_rejected"),
            ("Sec-Fetch-Site: cross-site\r\n", "status_dashboard_cross_site_request_rejected"),
        ]:
            request = (
                "POST /api/dashboard-stop-speech HTTP/1.1\r\n"
                "Host: inprocess.local\r\n"
                f"Authorization: {_STATUS_SMOKE_AUTH_HEADER}\r\n"
                f"{boundary_header}"
                "Content-Length: 0\r\n\r\n"
            ).encode("utf-8")
            status, headers, body = _raw_in_process_status_response(runtime, request)
            rejected = json.loads(body.decode("utf-8"))
            if status != 403 or rejected.get("error") != expected_error:
                raise SystemExit(
                    f"Status dashboard cross-site action boundary failed: {status}, {rejected}"
                )
            if headers.get("x-frame-options") != "DENY":
                raise SystemExit("Status dashboard cross-site rejection missed response security headers.")

        status, _, body = _raw_in_process_status_response(
            runtime,
            (
                "POST /api/dashboard-stop-speech HTTP/1.1\r\n"
                "Host: inprocess.local\r\n"
                f"Authorization: {_STATUS_SMOKE_AUTH_HEADER}\r\n"
                "Content-Length: 0\r\n\r\n"
            ).encode("utf-8"),
        )
        rejected = json.loads(body.decode("utf-8"))
        if status != 403 or rejected.get("error") != "status_dashboard_origin_required":
            raise SystemExit(
                f"Status dashboard accepted a state-changing request without Origin: {status}, {rejected}"
            )

        status, headers, body = _raw_in_process_status_response(
            runtime,
            (
                "POST /missing HTTP/1.1\r\n"
                "Host: inprocess.local\r\n"
                f"Authorization: {_STATUS_SMOKE_AUTH_HEADER}\r\n"
                "Origin: http://inprocess.local\r\n"
                "Content-Length: 0\r\n\r\n"
            ).encode("utf-8"),
        )
        if status != 404 or json.loads(body.decode("utf-8")).get("error") != "not_found":
            raise SystemExit("Status dashboard rejected a same-origin action before normal routing.")
        if headers.get("content-security-policy") != "default-src 'none'; frame-ancestors 'none'; base-uri 'none'":
            raise SystemExit("Status dashboard JSON/404 response missed its restrictive CSP.")


def _assert_status_skill_labels_keep_review_drafts_out_of_behavior() -> None:
    with TemporaryDirectory(prefix="jarvis-status-skill-labels-") as temp:
        runtime = make_temp_runtime(Path(temp))
        active_name = "Active Reviewed Workflow"
        active_trigger = "active-reviewed-workflow"
        draft_name = "Review Only Workflow Draft"
        draft_trigger = "review-only-workflow-draft"
        runtime.store.save_skill_with_projection_target(
            SkillRecord(
                name=active_name,
                trigger=active_trigger,
                body="Use this reviewed workflow only when its trigger matches.",
                tags="reviewed,status-smoke",
            )
        )
        runtime.store.save_skill_draft_with_projection_target(
            SkillRecord(
                name=draft_name,
                trigger=draft_trigger,
                body="This remains review-only and must never enter behavioral routing.",
                tags="draft,status-smoke",
            )
        )
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        runs_before = len(runtime.store.recent_tool_runs(limit=100))

        with _status_server_context(runtime) as base:
            status = _read_json(base + "/api/status")
            html = _read_text(base + "/")
            active_match = _read_json(
                base + "/api/skill-match-preview?request=" + quote(active_trigger)
            )
            draft_match = _read_json(
                base + "/api/skill-match-preview?request=" + quote(draft_trigger)
            )

        if status.get("skills") != 1 or status.get("review_skill_drafts") != 1:
            raise SystemExit(f"Status skill counts did not partition active and draft rows: {status}")
        if not isinstance(status.get("skills"), int) or not isinstance(
            status.get("review_skill_drafts"), int
        ):
            raise SystemExit("Status skill counters are not exact integers.")

        skill_summary = "\n".join(str(item) for item in status.get("skill_summary") or [])
        for expected in (
            "Active reviewed skills: 1",
            "Review-only skill drafts: 1",
            f"Active skill: {active_name} -> {active_trigger}",
            f"Review draft (not behaviorally reusable): {draft_name} -> {draft_trigger}",
            "skill matching uses active reviewed skills only",
        ):
            if expected.casefold() not in skill_summary.casefold():
                raise SystemExit(f"Status skill summary missed exact active/draft truth {expected!r}.")
        for false_claim in (
            "Saved reusable skills: 2",
            f"Active skill: {draft_name}",
            f"Skill: {draft_name}",
        ):
            if false_claim in skill_summary:
                raise SystemExit(f"Status skill summary made a draft reusable: {false_claim!r}.")

        for summary_key, exact_line in (
            ("chat_context_summary", "Active reviewed skills available: 1"),
            ("chat_safety_summary", "Active reviewed skills: 1"),
            ("brain_loop_summary", "Active reviewed reusable skills: 1"),
            ("learning_review_summary", "Active reviewed skills: 1"),
        ):
            summary_text = "\n".join(str(item) for item in status.get(summary_key) or [])
            if exact_line not in summary_text:
                raise SystemExit(f"{summary_key} did not count active reviewed skills only.")
        learning_text = "\n".join(
            str(item) for item in status.get("learning_review_summary") or []
        )
        if "Review-only skill drafts: 1" not in learning_text:
            raise SystemExit("Learning review did not expose the separate review-draft count.")
        for handoff_key in ("chat_context_handoff", "chat_safety_handoff"):
            handoff = status.get(handoff_key) or {}
            if handoff.get("saved_skill_count") != 1:
                raise SystemExit(f"{handoff_key} included a review draft in behavioral context.")

        for expected_html in (
            "<div>Active Skills</div><strong>1</strong>",
            "<div>Review Drafts</div><strong>1</strong>",
            "<h2>Active Skills &amp; Review Drafts</h2>",
            "Review draft (not behaviorally reusable)",
        ):
            if expected_html not in html:
                raise SystemExit(f"Dashboard HTML missed active/draft label {expected_html!r}.")

        active_output = str(active_match.get("output") or "")
        draft_output = str(draft_match.get("output") or "")
        if active_name not in active_output:
            raise SystemExit("Active reviewed skill was not behaviorally matchable.")
        if draft_name in active_output or draft_name in draft_output:
            raise SystemExit("Review-only draft leaked through behavioral skill matching.")
        if "active reviewed skills only" not in str(active_match.get("safety") or ""):
            raise SystemExit("Skill-match API safety text did not name the active-only boundary.")
        if len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
            raise SystemExit("Status skill inspection queued an approval.")
        if len(runtime.store.recent_tool_runs(limit=100)) != runs_before:
            raise SystemExit("Status skill inspection logged an execution side effect.")

    with TemporaryDirectory(prefix="jarvis-status-draft-only-") as temp:
        runtime = make_temp_runtime(Path(temp))
        runtime.store.save_skill_draft_with_projection_target(
            SkillRecord(
                name="Only Review Draft",
                trigger="only-review-draft",
                body="Review-only production-like fixture.",
                tags="draft,status-smoke",
            )
        )
        snapshot = status_server.build_status_snapshot(runtime)
        summary = "\n".join(snapshot.skill_summary)
        if snapshot.skills != 0 or snapshot.review_skill_drafts != 1:
            raise SystemExit("Draft-only status fixture claimed an active reviewed skill.")
        if (
            "No active reviewed skills yet" not in summary
            or "Review draft (not behaviorally reusable): Only Review Draft" not in summary
            or "Active skill: Only Review Draft" in summary
        ):
            raise SystemExit("Draft-only status summary did not remain review-only.")


def _assert_no_private_channel_fragments(label: str, payload: str) -> None:
    for fragment in [
        "SHOULD NOT APPEAR",
        "secret message",
        "BotFather",
        "Fixture",
        "+15555550123",
        "LIVE OUTPUT",
        "FAILURE OUTPUT",
        "KAKAO OUTPUT",
        "CALL OUTPUT",
        "IMESSAGE OUTPUT",
        "OLD OUTPUT",
    ]:
        if fragment in payload:
            raise SystemExit(f"{label} leaked private audit fragment {fragment!r}: {payload}")


def _assert_channel_health_api_metadata_only() -> None:
    with TemporaryDirectory(prefix="jarvis-status-channel-health-") as temp:
        runtime = make_temp_runtime(Path(temp))
        _seed_channel_runs(runtime)
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        with _status_server_context(runtime) as base:
            data = _read_json(base + "/api/channel-health")
            status = _read_json(base + "/api/status")
            with urllib.request.urlopen(base + "/", timeout=5) as response:
                html = response.read().decode("utf-8")
        if not data.get("ok") or data.get("tool") != "channel_health":
            raise SystemExit(f"Channel health API returned wrong tool payload: {data}")
        if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
            raise SystemExit(f"Channel health API should not queue approvals: {data}")
        metadata = data.get("metadata") or {}
        if data.get("content_suppressed") is not True or metadata.get("content_suppressed") is not True:
            raise SystemExit(f"Channel health API should expose content suppression: {data}")
        for key in [
            "reads_message_content",
            "external_side_effect",
            "executes_side_effect",
            "queues_approval",
            "controls_computer",
            "writes_database",
        ]:
            if metadata.get(key) is not False:
                raise SystemExit(f"Channel health API unsafe metadata {key}: {metadata}")
        output = str(data.get("output") or "")
        for expected in [
            "Jarvis channel health report:",
            "Telegram messages (send_telegram)",
            "last failure stage telegram_enter_did_not_send",
            "KakaoTalk messages (send_kakao)",
            "last failure stage chat_not_verified",
            "Instagram calls (call_instagram)",
            "iMessage (send_imessage)",
        ]:
            if expected not in output:
                raise SystemExit(f"Channel health API missed {expected!r}: {output}")
        payload_text = json.dumps(data, ensure_ascii=False)
        _assert_no_private_channel_fragments("Channel health API", payload_text)
        channels = {row["channel"]: row for row in data.get("channels", [])}
        if channels.get("telegram_message", {}).get("last_failure_stage") != "telegram_enter_did_not_send":
            raise SystemExit(f"Channel health API missed telegram failure stage: {channels}")
        status_payload = json.dumps(status, ensure_ascii=False)
        _assert_no_private_channel_fragments("/api/status", status_payload)
        status_health = status.get("channel_health_summary") or []
        status_health_text = "\n".join(str(item) for item in status_health)
        for expected in [
            "Channel health uses existing audit metadata only.",
            "Telegram Message:",
            "telegram_enter_did_not_send",
            "Content suppression: on",
        ]:
            if expected not in status_health_text:
                raise SystemExit(f"/api/status channel health summary missed {expected!r}: {status_health}")
        after_action_text = json.dumps(status.get("after_action_learning_summary") or {}, ensure_ascii=False)
        _assert_no_private_channel_fragments("/api/status after-action learning summary", after_action_text)
        for expected in [
            "<h2>Channel Health</h2>",
            "Channel health uses existing audit metadata only.",
            "telegram_enter_did_not_send",
            "Content suppression: on",
        ]:
            if expected not in html:
                raise SystemExit(f"Channel health dashboard panel missed {expected!r}")
        _assert_no_private_channel_fragments("Channel health dashboard panel", html)


def _assert_channel_health_dashboard_marks_bounded_sample() -> None:
    with TemporaryDirectory(prefix="jarvis-status-channel-bounded-") as temp:
        runtime = make_temp_runtime(Path(temp))
        for index in range(MAX_ROWS + 1):
            runtime.store.log_tool_run(
                "smoke",
                "send_telegram",
                "HIGH_RISK",
                True,
                True,
                f"STATUS BOUNDED OUTPUT {index} SHOULD NOT APPEAR",
                metadata={"to": f"Status Bounded Recipient {index} SHOULD NOT APPEAR"},
            )

        with _status_server_context(runtime) as base:
            data = _read_json(base + "/api/channel-health")
            status = _read_json(base + "/api/status")
            with urllib.request.urlopen(base + "/", timeout=5) as response:
                html = response.read().decode("utf-8")

        if data.get("row_sample_truncated") is not True:
            raise SystemExit(f"Channel health API should expose bounded sample marker: {data}")
        api_summary_text = "\n".join(str(item) for item in data.get("summary") or [])
        if "Bounded sample: older matching audit rows may exist beyond the row limit." not in api_summary_text:
            raise SystemExit(f"Channel health API summary missed bounded sample warning: {data}")
        status_health = status.get("channel_health_summary") or []
        status_health_text = "\n".join(str(item) for item in status_health)
        bounded_line = "rows reviewed: 500 / 500 (bounded sample; older matching rows may exist)."
        if bounded_line not in status_health_text:
            raise SystemExit(f"/api/status channel health summary missed bounded sample marker: {status_health}")
        if bounded_line not in html:
            raise SystemExit("Channel health dashboard panel missed bounded sample marker.")
        payload = json.dumps(data, ensure_ascii=False) + "\n" + json.dumps(status, ensure_ascii=False) + "\n" + html
        for fragment in ["STATUS BOUNDED OUTPUT", "Status Bounded Recipient", "SHOULD NOT APPEAR"]:
            if fragment in payload:
                raise SystemExit(f"Channel health bounded dashboard leaked fixture {fragment!r}: {payload}")


def _assert_channel_health_api_fails_closed_on_tool_error() -> None:
    with TemporaryDirectory(prefix="jarvis-status-channel-error-") as temp:
        runtime = make_temp_runtime(Path(temp))

        def broken_channel_health(_: dict) -> ToolResult:
            raise RuntimeError("SHOULD NOT APPEAR BotFather secret message Fixture +15555550123")

        runtime.registry._tools["channel_health"] = Tool(
            "channel_health",
            "Controlled smoke failure.",
            RiskLevel.READ_ONLY,
            broken_channel_health,
            "personal",
        )
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        with _status_server_context(runtime) as base:
            data = _read_json(base + "/api/channel-health")
            status = _read_json(base + "/api/status")
            with urllib.request.urlopen(base + "/", timeout=5) as response:
                html = response.read().decode("utf-8")

        if data.get("ok") is not False or data.get("tool") != "channel_health":
            raise SystemExit(f"Channel health API should fail closed on tool errors: {data}")
        if data.get("output") != "Channel health tool unavailable.":
            raise SystemExit(f"Channel health API exposed unexpected failure output: {data}")
        if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
            raise SystemExit(f"Channel health API failure path should not queue approvals: {data}")
        metadata = data.get("metadata") or {}
        if data.get("content_suppressed") is not True or metadata.get("content_suppressed") is not True:
            raise SystemExit(f"Channel health API failure path should keep suppression on: {data}")
        if metadata.get("diagnostic") != "RuntimeError":
            raise SystemExit(f"Channel health API failure path should expose only the exception type: {data}")
        for key in [
            "reads_message_content",
            "external_side_effect",
            "executes_side_effect",
            "queues_approval",
            "controls_computer",
            "writes_database",
        ]:
            if metadata.get(key) is not False:
                raise SystemExit(f"Channel health API failure path unsafe metadata {key}: {metadata}")
        summary_text = "\n".join(str(item) for item in data.get("summary") or [])
        for expected in [
            "Channel health tool unavailable.",
            "Diagnostic: RuntimeError",
            "Planner aliases remain frozen until the operator posts the live channel proof results.",
        ]:
            if expected not in summary_text:
                raise SystemExit(f"Channel health API failure summary missed {expected!r}: {data}")
        payload = json.dumps(data, ensure_ascii=False)
        _assert_no_private_channel_fragments("Channel health API failure fallback", payload)
        status_summary = "\n".join(str(item) for item in status.get("channel_health_summary") or [])
        if status.get("channel_health_unavailable") is not True:
            raise SystemExit(f"/api/status should mark channel health unavailable: {status}")
        if status.get("channel_health_diagnostic") != "RuntimeError":
            raise SystemExit(f"/api/status should expose only channel health exception type: {status}")
        for expected in ["Channel health tool unavailable.", "Diagnostic: RuntimeError"]:
            if expected not in status_summary or expected not in html:
                raise SystemExit(f"Status dashboard missed channel health failure marker {expected!r}: {status_summary}")
        combined = json.dumps(status, ensure_ascii=False) + "\n" + html
        _assert_no_private_channel_fragments("Channel health status failure fallback", combined)


