def _assert_approvals_api_failure_payload(
    *,
    label: str,
    data: dict,
    status_code: int,
    diagnostic: str,
    leak_marker: str,
    runtime_pending_count: int,
    approvals_before: int,
) -> None:
    if status_code != 503:
        raise SystemExit(f"{label} should use HTTP 503: {status_code}, {data}")
    if data.get("ok") is not False or data.get("review") != "Approvals unavailable.":
        raise SystemExit(f"{label} should fail closed with bounded review text: {data}")
    if data.get("count") != approvals_before or data.get("pending_approvals") != approvals_before:
        raise SystemExit(f"{label} should expose only pending approval count: {data}")
    if data.get("approvals") != []:
        raise SystemExit(f"{label} should suppress pending approval rows: {data}")
    if data.get("queued_approvals") != 0 or runtime_pending_count != approvals_before:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    if data.get("approval_review_unavailable") is not True or data.get("content_suppressed") is not True:
        raise SystemExit(f"{label} should expose unavailable marker: {data}")
    for key in [
        "approval_review_handoff_ready",
        "approval_review_items",
        "approval_review_next_commands",
        "approval_review_next_command_count",
        "approval_review_first_approval_id",
        "approval_review_first_tool_name",
        "approval_review_first_readiness_command",
        "approval_review_first_last_look_command",
        "approval_review_first_proof_command",
        "approval_review_first_verification_command",
        "approval_review_first_approve_command",
        "approval_review_first_dismiss_command",
        "next_command",
        "next_required_command",
        "next_proof_command",
    ]:
        value = data.get(key)
        if value not in (False, None, [], 0):
            raise SystemExit(f"{label} should suppress forged review field {key}: {data}")
    metadata = data.get("metadata") or {}
    if metadata.get("diagnostic") != diagnostic or metadata.get("tool_unavailable") is not True:
        raise SystemExit(f"{label} should expose bounded diagnostic: {data}")
    for key in [
        "calls_model",
        "executes_tools",
        "queues_approval",
        "approval_granted",
        "authorizes_execution",
        "authorizes_completion_claim",
        "connects_accounts",
        "calls_external_services",
        "writes_files",
        "writes_memory",
        "writes_notes",
        "writes_database",
        "reads_private_data",
        "external_side_effect",
        "controls_computer",
        "secret",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in [
        "Approvals API: `/api/approvals`",
        "Approvals unavailable.",
        f"Diagnostic: {diagnostic}",
        "never approves, dismisses, reruns, executes tools, or queues approvals",
    ]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "")
    for expected in ["read-only", "without approving", "dismissing", "rerunning", "queuing approvals"]:
        if expected not in safety.lower():
            raise SystemExit(f"{label} missed safety copy {expected!r}: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    for forbidden in [
        leak_marker,
        "가상연락처이",
        "private-approval-list",
        "/\x55sers/operator",
        "approve approval 99",
        "approval packet 99",
        "approval chain proof 99",
        "send_telegram",
    ]:
        if forbidden in payload:
            raise SystemExit(f"{label} leaked {forbidden!r}: {payload}")


