def _assert_approval_control_endpoint_failure_payload(
    *,
    label: str,
    data: dict,
    status_code: int,
    tool_name: str,
    output: str,
    unavailable_key: str,
    api_summary: str,
    diagnostic: str,
    hostile_id: str,
    leak_marker: str,
    runtime_pending_count: int,
    approvals_before: int,
) -> None:
    if status_code != 503:
        raise SystemExit(f"{label} should use HTTP 503: {status_code}, {data}")
    if data.get("ok") is not False or data.get("tool") != tool_name or data.get("output") != output:
        raise SystemExit(f"{label} should fail closed for {tool_name}: {data}")
    if data.get("approval_id") != "":
        raise SystemExit(f"{label} should suppress raw approval id: {data}")
    if data.get("approval_id_supplied") is not True or data.get("approval_id_length") != len(hostile_id):
        raise SystemExit(f"{label} should expose bounded id shape: {data}")
    expected_hash = hashlib.sha256(hostile_id.encode("utf-8")).hexdigest()[:16]
    if data.get("approval_id_hash") != expected_hash:
        raise SystemExit(f"{label} should expose bounded id hash: {data}")
    if data.get("queued_approvals") != 0 or runtime_pending_count != approvals_before:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    if data.get(unavailable_key) is not True or data.get("content_suppressed") is not True:
        raise SystemExit(f"{label} should expose unavailable marker: {data}")
    if "packet" in unavailable_key and data.get("preview_token") != "":
        raise SystemExit(f"{label} should suppress approval preview token: {data}")
    if "packet" in unavailable_key or "chain" in unavailable_key:
        if data.get("next_required_command") is not None or data.get("next_proof_command") is not None:
            raise SystemExit(f"{label} should suppress forged next/proof commands: {data}")
    metadata = data.get("metadata") or {}
    if metadata.get("diagnostic") != diagnostic or metadata.get("tool_unavailable") is not True:
        raise SystemExit(f"{label} should expose bounded diagnostic: {data}")
    for key in [
        "calls_model",
        "executes_tools",
        "queues_approval",
        "approval_granted",
        "authorizes_execution",
        "authorizes_completion_claim",
        "connects_accounts",
        "calls_external_services",
        "writes_files",
        "writes_memory",
        "writes_notes",
        "writes_database",
        "reads_private_data",
        "external_side_effect",
        "controls_computer",
        "secret",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in [
        api_summary,
        output,
        f"Diagnostic: {diagnostic}",
        "never approves, dismisses, reruns, executes tools, or queues approvals",
    ]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "")
    for expected in ["read-only", "without approving", "dismissing", "rerunning", "queuing approvals"]:
        if expected not in safety.lower():
            raise SystemExit(f"{label} missed safety copy {expected!r}: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    for forbidden in [
        leak_marker,
        hostile_id,
        "가상연락처이",
        "private-approval-control",
        "/\x55sers/operator",
        "approve approval 99",
        "approval packet 99",
        "approval chain proof 99",
    ]:
        if forbidden in payload:
            raise SystemExit(f"{label} leaked {forbidden!r}: {payload}")


