def _assert_capability_inspection_failure_payload(
    *,
    label: str,
    status_code: int,
    data: dict,
    runtime,
    approvals_before: int,
    tool_name: str,
    output: str,
    unavailable_key: str,
    diagnostic: str,
    summary_anchor: str,
    leak_marker: str,
    hidden_field: str | None = None,
) -> None:
    if status_code != 503:
        raise SystemExit(f"{label} should use HTTP 503: {status_code}, {data}")
    if data.get("ok") is not False or data.get("tool") != tool_name:
        raise SystemExit(f"{label} should fail closed for {tool_name}: {data}")
    if data.get("output") != output:
        raise SystemExit(f"{label} exposed unexpected output: {data}")
    if hidden_field and data.get(hidden_field) != "":
        raise SystemExit(f"{label} should suppress {hidden_field}: {data}")
    if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    if data.get(unavailable_key) is not True or data.get("content_suppressed") is not True:
        raise SystemExit(f"{label} should expose unavailable marker: {data}")
    metadata = data.get("metadata") or {}
    if metadata.get("diagnostic") != diagnostic or metadata.get("tool_unavailable") is not True:
        raise SystemExit(f"{label} should expose bounded diagnostic: {data}")
    for key in [
        "calls_model",
        "executes_tools",
        "queues_approval",
        "approval_granted",
        "authorizes_execution",
        "authorizes_completion_claim",
        "connects_accounts",
        "calls_external_services",
        "writes_files",
        "writes_memory",
        "writes_notes",
        "writes_database",
        "reads_private_data",
        "external_side_effect",
        "controls_computer",
        "secret",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in [summary_anchor, output, f"Diagnostic: {diagnostic}"]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "").lower()
    for expected in ["read-only", "without running tools", "approving requests", "private data", "queuing approvals"]:
        if expected not in safety:
            raise SystemExit(f"{label} missed safety copy {expected!r}: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    if leak_marker in payload or "approve approval 99" in payload:
        raise SystemExit(f"{label} leaked fixture {leak_marker!r}: {payload}")


