def _assert_capability_cockpit_status_carries_attention_reasons() -> None:
    leak_marker = "/\x55sers/hostile/status-cockpit-reason"
    with TemporaryDirectory(prefix="jarvis-status-cockpit-attention-") as temp:
        runtime = make_temp_runtime(Path(temp))
        runtime.store.log_tool_run(
            session_id=runtime.session_id,
            tool_name="send_telegram",
            risk="HIGH_RISK",
            ok=False,
            approved=True,
            output=f"SHOULD NOT APPEAR {leak_marker}",
            metadata={"failure_kind": f"transport_error {leak_marker}"},
        )
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        with _status_server_context(runtime) as base:
            status = _read_json(base + "/api/status")

        if len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
            raise SystemExit("/api/status capability cockpit snapshot should not queue approvals")
        if status.get("capability_cockpit_direction_summary") != "One Jarvis coordinator, visible capability cockpit, internal workers only.":
            raise SystemExit(f"/api/status lost cockpit direction summary: {status}")
        direction_principles = [str(item) for item in (status.get("capability_cockpit_direction_principles") or [])]
        if not any("Do not add Zoey-style companion identities" in item for item in direction_principles):
            raise SystemExit(f"/api/status lost companion-identity direction guardrail: {status}")
        if not any("subagents/internal workers invisible as personas" in item for item in direction_principles):
            raise SystemExit(f"/api/status lost internal-worker direction guardrail: {status}")
        lanes = {str(lane.get("key")): lane for lane in (status.get("capability_cockpit_lanes") or [])}
        messaging = lanes.get("messaging")
        if not messaging:
            raise SystemExit(f"/api/status missed messaging capability cockpit lane: {status}")
        if messaging.get("status") != "attention":
            raise SystemExit(f"/api/status should carry messaging attention state: {messaging}")
        reasons = [str(reason) for reason in (messaging.get("attention_reasons") or [])]
        if not any("latest failure: transport_error" in reason for reason in reasons):
            raise SystemExit(f"/api/status missed cockpit attention reason: {messaging}")
        if not any("<local-path>" in reason for reason in reasons):
            raise SystemExit(f"/api/status should carry redacted cockpit attention reason: {messaging}")
        if messaging.get("next_command") != "channel health" or messaging.get("next_command_kind") != "diagnostic":
            raise SystemExit(f"/api/status missed cockpit diagnostic next command: {messaging}")
        if status.get("capability_cockpit_next_command") != "channel health":
            raise SystemExit(f"/api/status should prioritize the cockpit diagnostic next command: {status}")
        queue = status.get("capability_cockpit_next_command_queue") or []
        if not queue or queue[0].get("command") != "channel health" or queue[0].get("kind") != "diagnostic":
            raise SystemExit(f"/api/status missed cockpit next-command queue priority: {status}")
        if status.get("capability_cockpit_next_commands", [None])[0] != "channel health":
            raise SystemExit(f"/api/status missed flattened cockpit next commands: {status}")
        counts = status.get("capability_cockpit_status_counts") or {}
        if counts.get("attention", 0) < 1:
            raise SystemExit(f"/api/status missed cockpit status counts: {status}")
        coverage = status.get("capability_cockpit_coverage_summary") or {}
        if not isinstance(coverage, dict) or "tools " not in str(coverage.get("summary") or ""):
            raise SystemExit(f"/api/status missed cockpit coverage summary: {status}")
        if coverage.get("lane_count") != len(status.get("capability_cockpit_lanes") or []):
            raise SystemExit(f"/api/status cockpit coverage lane count diverged: {status}")
        if status.get("capability_cockpit_tool_coverage_ready_lane_count") != coverage.get("tool_ready_count"):
            raise SystemExit(f"/api/status cockpit tool coverage count diverged: {status}")
        if status.get("capability_cockpit_smoke_coverage_ready_lane_count") != coverage.get("smoke_ready_count"):
            raise SystemExit(f"/api/status cockpit smoke coverage count diverged: {status}")
        if coverage.get("hidden_smoke_metadata_count") != 0:
            raise SystemExit(f"/api/status should preserve hidden smoke metadata count: {status}")
        if coverage.get("hidden_tool_metadata_count") != 0:
            raise SystemExit(f"/api/status should preserve hidden tool metadata count: {status}")
        if status.get("capability_cockpit_approval_required_lane_count") != coverage.get("approval_required_count"):
            raise SystemExit(f"/api/status cockpit approval coverage count diverged: {status}")
        if status.get("capability_cockpit_auto_run_safe_lane_count") != coverage.get("auto_run_safe_count"):
            raise SystemExit(f"/api/status cockpit auto-run-safe count diverged: {status}")
        trust = status.get("capability_cockpit_trust_summary") or {}
        if not isinstance(trust, dict) or "trust checklist" not in str(trust.get("summary") or ""):
            raise SystemExit(f"/api/status missed cockpit earned-trust summary: {status}")
        if trust.get("lane_count") != len(status.get("capability_cockpit_lanes") or []):
            raise SystemExit(f"/api/status cockpit trust lane count diverged: {status}")
        if status.get("capability_cockpit_trust_ready") is not trust.get("trust_ready"):
            raise SystemExit(f"/api/status cockpit trust readiness diverged: {status}")
        if status.get("capability_cockpit_trust_ready_lane_count") != trust.get("trust_ready_lane_count"):
            raise SystemExit(f"/api/status cockpit trust ready-lane count diverged: {status}")
        if status.get("capability_cockpit_trust_partial_lane_count") != trust.get("trust_partial_lane_count"):
            raise SystemExit(f"/api/status cockpit trust partial-lane count diverged: {status}")
        checks = messaging.get("trust_checklist") or []
        labels = [str(item.get("label")) for item in checks if isinstance(item, dict)]
        for expected in ("registered tools", "aggregate smoke coverage", "approval boundary", "next command"):
            if expected not in labels:
                raise SystemExit(f"/api/status messaging lane lost trust check {expected!r}: {messaging}")
        if messaging.get("trust_non_authorizing") is not True:
            raise SystemExit(f"/api/status messaging lane trust checklist should stay non-authorizing: {messaging}")
        build_guardrails = lanes.get("build_guardrails")
        if not build_guardrails:
            raise SystemExit(f"/api/status missed build guardrails capability cockpit lane: {status}")
        guardrail_notes = [str(note) for note in (build_guardrails.get("guardrail_notes") or [])]
        if not any("live-proof freeze active" in note for note in guardrail_notes):
            raise SystemExit(f"/api/status missed build guardrail live-proof freeze note: {build_guardrails}")
        if build_guardrails.get("status") not in {"ready", "ok"}:
            raise SystemExit(f"/api/status should not present build guardrails as broken: {build_guardrails}")
        if "messaging" not in [str(key) for key in (status.get("capability_cockpit_attention") or [])]:
            raise SystemExit(f"/api/status missed cockpit attention lane key: {status}")
        payload = json.dumps(status, ensure_ascii=False)
        if leak_marker in payload or "SHOULD NOT APPEAR" in payload:
            raise SystemExit(f"/api/status leaked cockpit failure fixture: {payload}")


