def _assert_capability_cockpit_status_carries_approval_hold_receipt() -> None:
    with TemporaryDirectory(prefix="jarvis-status-cockpit-approval-held-") as temp:
        runtime = make_temp_runtime(Path(temp))
        approval_id = runtime.store.add_pending_approval(
            runtime.session_id,
            "send a telegram to me saying approval status proof",
            "send_telegram",
            "explicit approval required",
            {"to": "owner", "message": "approval status proof"},
        )
        runtime.store.log_tool_run(
            session_id=runtime.session_id,
            tool_name="send_telegram",
            risk="HIGH_RISK",
            ok=False,
            approved=False,
            approval_id=approval_id,
            output="approval required",
            metadata={"failure_kind": "approval_required"},
        )
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        with _status_server_context(runtime) as base:
            status = _read_json(base + "/api/status")

        if len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
            raise SystemExit("/api/status approval-held cockpit snapshot should not queue approvals")
        lanes = {str(lane.get("key")): lane for lane in (status.get("capability_cockpit_lanes") or [])}
        messaging = lanes.get("messaging")
        if not messaging:
            raise SystemExit(f"/api/status missed messaging cockpit lane for approval hold: {status}")
        if messaging.get("status") != "awaiting approval":
            raise SystemExit(f"/api/status should carry approval-held status: {messaging}")
        if "messaging" in [str(key) for key in (status.get("capability_cockpit_attention") or [])]:
            raise SystemExit(f"approval-held lane should not be counted as failed attention: {status}")
        if messaging.get("last_approval_id") != approval_id:
            raise SystemExit(f"/api/status missed linked approval id: {messaging}")
        if "send_telegram" not in str(messaging.get("last_approval_hold") or ""):
            raise SystemExit(f"/api/status missed approval-held tool receipt: {messaging}")
        if messaging.get("last_failure") or messaging.get("last_failure_kind"):
            raise SystemExit(f"/api/status approval-held lane should not carry failure fields: {messaging}")
        expected_commands = [
            f"approval readiness {approval_id}",
            f"approval packet {approval_id}",
            f"approval chain proof {approval_id}",
        ]
        if messaging.get("approval_next_commands") != expected_commands:
            raise SystemExit(f"/api/status missed approval review commands: {messaging}")
        if messaging.get("next_command") != f"approval readiness {approval_id}" or messaging.get("next_command_kind") != "approval_review":
            raise SystemExit(f"/api/status missed approval-held next command: {messaging}")
        if status.get("capability_cockpit_next_command") != f"approval readiness {approval_id}":
            raise SystemExit(f"/api/status should prioritize approval review globally: {status}")
        queue = status.get("capability_cockpit_next_command_queue") or []
        if not queue or queue[0].get("command") != f"approval readiness {approval_id}" or queue[0].get("kind") != "approval_review":
            raise SystemExit(f"/api/status missed approval review cockpit queue: {status}")
        if queue[0].get("last_failure") or queue[0].get("last_failure_kind"):
            raise SystemExit(f"/api/status approval-held queue should not carry failure fields: {queue[0]}")
        counts = status.get("capability_cockpit_status_counts") or {}
        if counts.get("awaiting approval", 0) < 1:
            raise SystemExit(f"/api/status missed approval-held status count: {status}")
        payload = json.dumps(status, ensure_ascii=False)
        if "approval required" in payload:
            raise SystemExit(f"/api/status leaked raw approval-held output: {payload}")


