def _assert_capability_cockpit_status_fails_closed_on_tool_error() -> None:
    leak_marker = "/\x55sers/hostile/status-cockpit-unavailable"
    with TemporaryDirectory(prefix="jarvis-status-cockpit-error-") as temp:
        runtime = make_temp_runtime(Path(temp))

        def broken_capability_cockpit(_: dict) -> ToolResult:
            raise RuntimeError(f"SHOULD NOT APPEAR {leak_marker}")

        runtime.registry._tools["capability_cockpit"] = Tool(
            "capability_cockpit",
            "Controlled smoke failure.",
            RiskLevel.READ_ONLY,
            broken_capability_cockpit,
        )
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        with _status_server_context(runtime) as base:
            status = _read_json(base + "/api/status")
            cockpit_status, cockpit = _read_json_allowing_error(base + "/api/cockpit")
            with urllib.request.urlopen(base + "/", timeout=5) as response:
                html = response.read().decode("utf-8")

        if len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
            raise SystemExit("/api/status cockpit failure path should not queue approvals")
        if cockpit_status != 503:
            raise SystemExit(f"/api/cockpit failure path should use HTTP 503: {cockpit_status}, {cockpit}")
        if status.get("capability_cockpit_unavailable") is not True:
            raise SystemExit(f"/api/status should mark cockpit unavailable: {status}")
        if status.get("capability_cockpit_diagnostic") != "RuntimeError":
            raise SystemExit(f"/api/status should expose only exception type: {status}")
        if status.get("capability_cockpit_lanes") != [] or status.get("capability_cockpit_attention") != []:
            raise SystemExit(f"/api/status cockpit failure path should not invent lane data: {status}")
        coverage = status.get("capability_cockpit_coverage_summary") or {}
        if coverage.get("lane_count") != 0 or coverage.get("summary") or status.get("capability_cockpit_coverage_ready") is not False:
            raise SystemExit(f"/api/status cockpit failure path should not invent coverage data: {status}")
        if coverage.get("hidden_smoke_metadata_count") != 0:
            raise SystemExit(f"/api/status cockpit failure path should zero hidden smoke metadata: {status}")
        trust = status.get("capability_cockpit_trust_summary") or {}
        if trust.get("lane_count") != 0 or trust.get("summary") or status.get("capability_cockpit_trust_ready") is not False:
            raise SystemExit(f"/api/status cockpit failure path should not invent trust data: {status}")
        cockpit_coverage = cockpit.get("coverage_summary") or {}
        if cockpit.get("ok") is not False or cockpit.get("error_type") != "RuntimeError":
            raise SystemExit(f"/api/cockpit should fail closed with exception type only: {cockpit}")
        if (
            cockpit_coverage.get("lane_count") != 0
            or cockpit_coverage.get("summary")
            or cockpit_coverage.get("hidden_smoke_metadata_count") != 0
            or cockpit.get("coverage_ready") is not False
        ):
            raise SystemExit(f"/api/cockpit failure path should expose zeroed coverage summary: {cockpit}")
        for key in [
            "capability_cockpit_tool_coverage_ready_lane_count",
            "capability_cockpit_smoke_coverage_ready_lane_count",
            "capability_cockpit_approval_required_lane_count",
            "capability_cockpit_auto_run_safe_lane_count",
            "capability_cockpit_trust_ready_lane_count",
            "capability_cockpit_trust_partial_lane_count",
        ]:
            if status.get(key) != 0:
                raise SystemExit(f"/api/status cockpit failure path should zero {key}: {status}")
        payload = json.dumps(status, ensure_ascii=False)
        payload += "\n" + json.dumps(cockpit, ensure_ascii=False)
        if leak_marker in payload or "SHOULD NOT APPEAR" in payload:
            raise SystemExit(f"/api/status leaked cockpit unavailable fixture: {payload}")
        for expected in [
            "snapshot?.capability_cockpit_unavailable === true",
            "capability_cockpit_diagnostic",
            "Jarvis — cockpit unavailable",
            "cockpitCoverageHost.dataset.coverageReady",
            "coverage unavailable",
            "cockpit-unavailable",
            "Capability cockpit unavailable.",
        ]:
            if expected not in html:
                raise SystemExit(f"Status dashboard missed cockpit unavailable renderer hook: {expected}")
        if leak_marker in html or "SHOULD NOT APPEAR" in html:
            raise SystemExit("Status dashboard leaked cockpit unavailable fixture into static HTML")


