def _assert_checkpoint_recovery_followthrough_api_failure_payload(
    *,
    label: str,
    status: int,
    data: dict,
    runtime,
    approvals_before: int,
    diagnostic: str,
    leak_fragments: list[str],
) -> None:
    if status != 503:
        raise SystemExit(f"{label} should use HTTP 503: {status}, {data}")
    if (
        data.get("ok") is not False
        or data.get("tool") != "checkpoint_recovery_followthrough_packet"
        or data.get("objective") != ""
        or data.get("output") != "Checkpoint recovery follow-through unavailable."
    ):
        raise SystemExit(f"{label} should fail closed without echoing query text: {data}")
    if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    expected_defaults = {
        "followthrough_state": "unavailable",
        "normal_followthrough_allowed": False,
        "recovery_closure_missing": ["checkpoint_recovery_followthrough_unavailable"],
        "recovery_closure_missing_count": 1,
        "receipt_file_sha256": "",
        "receipt_file_hash_present": False,
        "receipt_hash_matches_file": False,
        "checkpoint_file_sha256": "",
        "checkpoint_file_hash_present": False,
        "checkpoint_hash_matches_file": False,
        "recovery_artifact_hashes_match_files": False,
        "recovery_followthrough_token_sha256": "",
        "recovery_followthrough_token_present": False,
        "recovery_followthrough_token_boundary_rows": [],
        "recovery_followthrough_token_boundary_row_count": 0,
        "recovery_followthrough_token_boundary_ready": False,
        "recovery_followthrough_token_reusable_for_future_recovery": False,
        "recovery_followthrough_token_authorizes_resume_gate": False,
        "recovery_followthrough_token_authorizes_next_step": False,
        "recovery_followthrough_token_authorizes_risky_work": False,
        "recovery_followthrough_token_authorizes_approval": False,
        "recovery_followthrough_token_authorizes_model_call": False,
        "recovery_followthrough_token_authorizes_tool_execution": False,
        "recovery_followthrough_token_authorizes_personal_data_read": False,
        "recovery_followthrough_token_authorizes_external_side_effect": False,
        "next_recovery_followthrough_requires_new_token": True,
        "local_safe_recovery_execution_token_sha256": "",
        "local_safe_recovery_execution_token_present": False,
        "local_safe_recovery_execution_token_boundary_rows": [],
        "local_safe_recovery_execution_token_boundary_row_count": 0,
        "local_safe_recovery_execution_token_boundary_ready": False,
        "local_safe_recovery_execution_token_authorizes_resume_gate": False,
        "local_safe_recovery_execution_token_authorizes_next_step": False,
        "local_safe_recovery_execution_token_authorizes_risky_work": False,
        "local_safe_recovery_execution_token_authorizes_approval": False,
        "local_safe_recovery_execution_token_authorizes_model_call": False,
        "local_safe_recovery_execution_token_authorizes_tool_execution": False,
        "local_safe_recovery_execution_token_authorizes_personal_data_read": False,
        "local_safe_recovery_execution_token_authorizes_external_side_effect": False,
        "local_safe_recovery_execution_token_reusable_for_future_recovery": False,
        "next_recovery_execution_requires_new_local_safe_token": True,
        "recovery_execution_score": 0,
        "recovery_execution_max_score": 0,
        "recovery_execution_scorecard_rows": [],
        "recovery_execution_scorecard_row_count": 0,
        "recovery_execution_required_rows_ready": False,
        "recovery_execution_scorecard_ready": False,
        "recovery_execution_contract_fields": [],
        "recovery_execution_contract_field_count": 0,
        "recovery_execution_readiness_token_sha256": "",
        "recovery_execution_readiness_token_present": False,
        "recovery_execution_readiness_token_boundary_rows": [],
        "recovery_execution_readiness_token_boundary_row_count": 0,
        "recovery_execution_readiness_token_boundary_ready": False,
        "recovery_execution_readiness_as_prior_proof": False,
        "recovery_execution_readiness_token_authorizes_resume_gate": False,
        "recovery_execution_readiness_token_authorizes_next_step": False,
        "recovery_execution_readiness_token_authorizes_risky_work": False,
        "recovery_execution_readiness_token_authorizes_approval": False,
        "recovery_execution_readiness_token_authorizes_model_call": False,
        "recovery_execution_readiness_token_authorizes_tool_execution": False,
        "recovery_execution_readiness_token_authorizes_personal_data_read": False,
        "recovery_execution_readiness_token_authorizes_external_side_effect": False,
        "recovery_execution_readiness_token_authorizes_unreviewed_followthrough": False,
        "recovery_execution_readiness_token_reusable_for_future_recovery": False,
        "next_recovery_execution_requires_new_readiness_token": True,
        "recovery_execution_readiness_authorizes_action_now": False,
        "recovery_execution_readiness_authorizes_risky_work": False,
        "recovery_execution_readiness_authorizes_unreviewed_followthrough": False,
        "recovery_execution_readiness_authorizes_model_call": False,
        "recovery_execution_readiness_authorizes_tool_execution": False,
        "recovery_execution_readiness_authorizes_personal_data_read": False,
        "recovery_execution_readiness_authorizes_external_side_effect": False,
        "next_safe_command": "",
    }
    for key, expected in expected_defaults.items():
        if data.get(key) != expected:
            raise SystemExit(f"{label} should expose safe default {key}={expected!r}: {data}")
    if data.get("checkpoint_recovery_followthrough_unavailable") is not True or data.get("content_suppressed") is not True:
        raise SystemExit(f"{label} should expose unavailable marker: {data}")
    metadata = data.get("metadata") or {}
    if (
        metadata.get("diagnostic") != diagnostic
        or metadata.get("checkpoint_recovery_followthrough_unavailable") is not True
        or metadata.get("content_suppressed") is not True
    ):
        raise SystemExit(f"{label} should expose bounded diagnostic: {data}")
    for key in [
        "calls_model",
        "executes_tools",
        "queues_approval",
        "approval_granted",
        "authorizes_execution",
        "authorizes_completion_claim",
        "connects_accounts",
        "calls_external_services",
        "writes_files",
        "writes_memory",
        "writes_notes",
        "writes_database",
        "reads_private_data",
        "external_side_effect",
        "controls_computer",
        "secret",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in [
        "API: `/api/checkpoint-recovery-followthrough?step=...&verification=...&receipt=...&receipt_sha256=...&checkpoint=...&checkpoint_sha256=...&stop=...`",
        "Checkpoint recovery follow-through unavailable.",
        f"Diagnostic: {diagnostic}",
    ]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "").lower()
    for expected in [
        "read-only",
        "without running shell/code",
        "controlling the computer",
        "reading private data",
        "writing notes",
        "queuing approvals",
    ]:
        if expected not in safety:
            raise SystemExit(f"{label} missed safety copy {expected!r}: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    for fragment in leak_fragments:
        if fragment in payload:
            raise SystemExit(f"{label} leaked fixture {fragment!r}: {payload}")


