def _assert_build_selector_api_failure_payload(
    *,
    label: str,
    status: int,
    data: dict,
    runtime,
    approvals_before: int,
    tool_name: str,
    output: str,
    endpoint: str,
    diagnostic: str,
    leak_fragments: list[str],
    expected_empty_fields: dict[str, object],
) -> None:
    if status != 503:
        raise SystemExit(f"{label} should use HTTP 503: {status}, {data}")
    if data.get("ok") is not False or data.get("tool") != tool_name:
        raise SystemExit(f"{label} should fail closed for {tool_name}: {data}")
    if data.get("output") != output:
        raise SystemExit(f"{label} exposed unexpected output: {data}")
    if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    for key, expected in expected_empty_fields.items():
        if data.get(key) != expected:
            raise SystemExit(f"{label} should expose safe default {key}={expected!r}: {data}")
    metadata = data.get("metadata") or {}
    if (
        metadata.get("diagnostic") != diagnostic
        or metadata.get("build_selector_available") is not False
        or metadata.get("endpoint") != endpoint
        or metadata.get("objective_supplied") is not True
        or metadata.get("content_suppressed") is not True
    ):
        raise SystemExit(f"{label} should expose only bounded diagnostics: {data}")
    for key in [
        "calls_model",
        "executes_tools",
        "queues_approval",
        "approval_granted",
        "authorizes_execution",
        "authorizes_completion_claim",
        "changes_task_status",
        "completes_task",
        "writes_files",
        "writes_memory",
        "writes_notes",
        "writes_database",
        "reads_private_data",
        "external_side_effect",
        "controls_computer",
        "secret",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in ["API unavailable.", f"Diagnostic: {diagnostic}", "Fallback is read-only"]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "").lower()
    for expected in ["read-only", "does not edit files", "does not", "read private data", "queue approvals"]:
        if expected not in safety:
            raise SystemExit(f"{label} missed safety copy {expected!r}: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    for fragment in leak_fragments:
        if fragment in payload:
            raise SystemExit(f"{label} leaked fixture {fragment!r}: {payload}")


