def _assert_spoken_turn_rehearsal_failure_payload(
    data: dict,
    *,
    label: str,
    diagnostic: str,
    requested_message: str,
    approvals_before: int,
    runtime,
) -> None:
    metadata = data.get("metadata") or {}
    if data.get("ok") is not False or data.get("tool") != "spoken_turn_rehearsal":
        raise SystemExit(f"{label} should fail closed: {data}")
    if "message" in data:
        raise SystemExit(f"{label} should not echo raw spoken messages: {data}")
    if metadata.get("message") is not None:
        raise SystemExit(f"{label} should not reuse raw message metadata: {metadata}")
    if data.get("output") != "Spoken turn rehearsal unavailable.":
        raise SystemExit(f"{label} exposed unexpected failure output: {data}")
    if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    if metadata.get("diagnostic") != diagnostic:
        raise SystemExit(f"{label} should expose bounded diagnostic {diagnostic!r}: {data}")
    if metadata.get("message_supplied") is not True or data.get("message_supplied") is not True:
        raise SystemExit(f"{label} should preserve message presence only: {data}")
    if metadata.get("message_chars") != len(requested_message) or data.get("message_chars") != len(requested_message):
        raise SystemExit(f"{label} should expose message length only: {data}")
    if not metadata.get("message_hash") or data.get("message_hash") != metadata.get("message_hash"):
        raise SystemExit(f"{label} should expose bounded message hash: {data}")
    if data.get("route_preview_available") is not False or metadata.get("route_preview_available") is not False:
        raise SystemExit(f"{label} should not claim route preview: {data}")
    if data.get("planned_actions") != [] or metadata.get("planned_actions") != []:
        raise SystemExit(f"{label} should not reuse planned actions: {data}")
    if data.get("recommended_next_commands") != [] or metadata.get("recommended_next_commands") != []:
        raise SystemExit(f"{label} should not reuse next commands: {data}")
    for key in [
        "calls_model",
        "calls_chat_model",
        "speaks_audio",
        "records_audio",
        "starts_listener",
        "requests_microphone_access",
        "microphone_access_requested",
        "transcribes_audio",
        "saves_transcript",
        "executes_tools",
        "writes_memory",
        "queues_approval",
        "approval_required",
        "approval_granted",
        "authorizes_execution",
        "routes_actions",
        "external_side_effect",
        "controls_computer",
        "writes_database",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
        if data.get(key) is not None and data.get(key) is not False:
            raise SystemExit(f"{label} unsafe top-level {key}: {data}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in [
        "Spoken turn rehearsal unavailable.",
        f"Diagnostic: {diagnostic}",
        "raw spoken message is not included",
        "No route preview was computed",
        "No chat model call, speech output, microphone access",
        "/api/spoken-turn-rehearsal",
    ]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "")
    if "read-only" not in safety.lower() or "without calling a chat model" not in safety:
        raise SystemExit(f"{label} missed read-only safety copy: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    for fragment in [
        "가상연락처이",
        "비밀메시지",
        "send telegram",
        "approve approval 99",
        "BotFather",
        "+15555550123",
        requested_message,
    ]:
        if fragment in payload:
            raise SystemExit(f"{label} leaked fixture {fragment!r}: {payload}")


