def _assert_voice_command_cockpit_api_failure_payload(
    *,
    label: str,
    data: dict,
    runtime,
    approvals_before: int,
    diagnostic: str,
) -> None:
    if data.get("ok") is not False or data.get("tool") != "voice_command_cockpit":
        raise SystemExit(f"{label} should fail closed: {data}")
    for raw_key in ["transcript", "confirmed", "mode"]:
        if raw_key in data:
            raise SystemExit(f"{label} should not echo raw {raw_key}: {data}")
    if data.get("output") != "Voice command cockpit unavailable.":
        raise SystemExit(f"{label} exposed unexpected output: {data}")
    if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    metadata = data.get("metadata") or {}
    if metadata.get("diagnostic") != diagnostic:
        raise SystemExit(f"{label} should expose only the bounded diagnostic: {data}")
    for key in [
        "transcript_supplied",
        "confirmed_supplied",
        "mode_supplied",
        "privacy_receipt_id_supplied",
        "confirmation_receipt_id_supplied",
        "confirmation_receipt_nonce_supplied",
    ]:
        if metadata.get(key) is not True or data.get(key) is not True:
            raise SystemExit(f"{label} missed supplied flag {key}: {data}")
    if metadata.get("confirmed_value") is not True or data.get("confirmed_value") is not True:
        raise SystemExit(f"{label} should preserve normalized confirmation only: {data}")
    for hash_key in [
        "transcript_hash",
        "mode_hash",
        "privacy_receipt_id_hash",
        "confirmation_receipt_id_hash",
        "confirmation_receipt_nonce_hash",
    ]:
        if not metadata.get(hash_key) or data.get(hash_key) != metadata.get(hash_key):
            raise SystemExit(f"{label} should expose bounded {hash_key}: {data}")
    if metadata.get("transcript_chars", 0) <= 0 or data.get("transcript_chars") != metadata.get("transcript_chars"):
        raise SystemExit(f"{label} should expose transcript length only: {data}")
    for key in [
        "receipt_id",
        "confirmation_receipt_nonce",
        "supplied_confirmation_receipt_id",
        "supplied_confirmation_receipt_nonce",
        "receipt_route_state",
        "route_gate_state",
        "runtime_entry_mode",
        "privacy_receipt_id",
        "supplied_privacy_receipt_id",
        "transcript_sha256",
        "voice_command_intake_contract_sha256",
        "voice_command_intake_contract_privacy_receipt_id",
        "voice_command_intake_contract_confirmation_receipt_id",
        "voice_command_intake_contract_confirmation_receipt_nonce",
        "voice_command_intake_contract_route_gate_state",
        "next_command",
    ]:
        if metadata.get(key) != "" or (key in data and data.get(key) != ""):
            raise SystemExit(f"{label} should not echo or invent {key}: {data}")
    if data.get("cockpit_available") is not False or metadata.get("cockpit_available") is not False:
        raise SystemExit(f"{label} should mark cockpit unavailable: {data}")
    if data.get("cockpit_state") != "VOICE_COMMAND_COCKPIT_UNAVAILABLE" or metadata.get("cockpit_state") != "VOICE_COMMAND_COCKPIT_UNAVAILABLE":
        raise SystemExit(f"{label} should mark cockpit unavailable state: {data}")
    if data.get("route_proof_bundle_state") != "VOICE_ROUTE_PROOF_UNAVAILABLE" or metadata.get("route_proof_bundle_state") != "VOICE_ROUTE_PROOF_UNAVAILABLE":
        raise SystemExit(f"{label} should mark route proof unavailable: {data}")
    if data.get("runtime_bridge_state") != "VOICE_RUNTIME_BRIDGE_UNAVAILABLE" or metadata.get("runtime_bridge_state") != "VOICE_RUNTIME_BRIDGE_UNAVAILABLE":
        raise SystemExit(f"{label} should mark runtime bridge unavailable: {data}")
    if data.get("voice_command_intake_contract_runtime_bridge_state") != "VOICE_RUNTIME_BRIDGE_UNAVAILABLE":
        raise SystemExit(f"{label} should mark command-intake bridge state unavailable: {data}")
    if data.get("voice_command_intake_contract_route_proof_bundle_state") != "VOICE_ROUTE_PROOF_UNAVAILABLE":
        raise SystemExit(f"{label} should mark command-intake route proof state unavailable: {data}")
    if data.get("missing_blockers") != ["voice command cockpit unavailable"] or metadata.get("missing_blocker_count") != 1:
        raise SystemExit(f"{label} should keep a bounded missing cockpit proof: {data}")
    if data.get("outputs") != {"receipt": "", "route_gate": "", "route_proof_bundle": "", "runtime_bridge": ""}:
        raise SystemExit(f"{label} should not expose nested outputs: {data}")
    for key in [
        "receipt_nonce_required",
        "next_voice_review_requires_fresh_command_intake_contract",
    ]:
        if data.get(key) is not True or metadata.get(key) is not True:
            raise SystemExit(f"{label} should keep {key}=True: {data}")
    for key in [
        "ready_for_command_intake",
        "hash_match",
        "receipt_id_match",
        "receipt_nonce_match",
        "receipt_freshness_match",
        "privacy_receipt_match",
        "can_enter_runtime",
        "can_auto_execute_now",
        "can_emit_executable_tool_action",
        "approval_required_after_bridge",
        "voice_command_intake_contract_present",
        "voice_command_intake_contract_ready",
        "voice_command_intake_contract_authorizes_action_now",
        "voice_command_intake_contract_authorizes_model_call",
        "voice_command_intake_contract_authorizes_tool_execution",
        "voice_command_intake_contract_authorizes_approval",
        "voice_command_intake_contract_authorizes_routing",
        "voice_command_intake_contract_authorizes_transcript_mutation",
        "voice_command_intake_contract_authorizes_personal_data_read",
        "voice_command_intake_contract_authorizes_external_side_effect",
        "voice_command_intake_contract_reusable_for_next_voice_review",
        "calls_model",
        "calls_chat_model",
        "speaks_audio",
        "records_audio",
        "starts_listener",
        "requests_microphone_access",
        "microphone_access_requested",
        "transcribes_audio",
        "saves_transcript",
        "executes_tools",
        "writes_memory",
        "queues_approval",
        "approval_granted",
        "authorizes_execution",
        "routes_actions",
        "external_side_effect",
        "controls_computer",
        "writes_database",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
        if data.get(key) is not None and data.get(key) is not False:
            raise SystemExit(f"{label} unsafe top-level {key}: {data}")
    for key in [
        "required_commands",
        "voice_command_intake_contract_proof_commands",
        "proof_commands",
        "recommended_next_commands",
        "planned_actions",
    ]:
        if data.get(key) not in (None, []) or metadata.get(key) != []:
            raise SystemExit(f"{label} should not invent {key}: {data}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in [
        "Voice command cockpit unavailable.",
        f"Diagnostic: {diagnostic}",
        "raw transcript and supplied proof tokens are not included",
        "No command-intake contract, runtime entry, route unlock",
        "Voice command intake remains blocked",
        "No chat model call, speech output, microphone access",
        "/api/voice-command-cockpit",
    ]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "")
    if "read-only" not in safety.lower() or "without recording audio" not in safety:
        raise SystemExit(f"{label} missed read-only safety copy: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    for fragment in ["가상연락처이", "비밀메시지"]:
        if fragment in payload:
            raise SystemExit(f"{label} leaked CJK/private fragment {fragment!r}: {payload}")


