def _assert_voice_post_run_closure_api_failure_payload(
    *,
    label: str,
    data: dict,
    runtime,
    approvals_before: int,
    diagnostic: str,
) -> None:
    if data.get("ok") is not False or data.get("tool") != "voice_post_run_closure_packet":
        raise SystemExit(f"{label} should return a failed voice_post_run_closure_packet payload: {data}")
    if data.get("output") != "Voice post-run closure unavailable.":
        raise SystemExit(f"{label} should use bounded unavailable output: {data}")
    if data.get("pending_approvals") != approvals_before or data.get("queued_approvals") != 0:
        raise SystemExit(f"{label} should not queue approvals: {data}")
    if len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
        raise SystemExit(f"{label} changed pending approvals.")
    metadata = data.get("metadata") or {}
    if metadata.get("diagnostic") != diagnostic:
        raise SystemExit(f"{label} missed diagnostic {diagnostic!r}: {data}")
    for raw_key in ["transcript", "confirmed", "mode", "evidence", "verification", "post_health", "post_audit", "learning"]:
        if raw_key in data:
            raise SystemExit(f"{label} should not echo raw {raw_key}: {data}")
    for key in [
        "transcript_supplied",
        "confirmed_supplied",
        "mode_supplied",
        "privacy_receipt_id_supplied",
        "confirmation_receipt_id_supplied",
        "confirmation_receipt_nonce_supplied",
        "evidence_supplied",
        "verification_supplied",
        "post_health_supplied",
        "post_audit_supplied",
        "learning_supplied",
    ]:
        if metadata.get(key) is not True or data.get(key) is not True:
            raise SystemExit(f"{label} missed supplied flag {key}: {data}")
    if metadata.get("confirmed_value") is not True or data.get("confirmed_value") is not True:
        raise SystemExit(f"{label} should preserve normalized confirmation only: {data}")
    for hash_key in [
        "transcript_hash",
        "mode_hash",
        "privacy_receipt_id_hash",
        "confirmation_receipt_id_hash",
        "confirmation_receipt_nonce_hash",
        "evidence_hash",
        "verification_hash",
        "post_health_hash",
        "post_audit_hash",
        "learning_hash",
    ]:
        if not metadata.get(hash_key) or data.get(hash_key) != metadata.get(hash_key) or len(str(data.get(hash_key))) != 16:
            raise SystemExit(f"{label} should expose bounded {hash_key}: {data}")
    if metadata.get("transcript_chars", 0) <= 0 or data.get("transcript_chars") != metadata.get("transcript_chars"):
        raise SystemExit(f"{label} should expose transcript length only: {data}")
    if metadata.get("evidence_chars", 0) <= 0 or data.get("evidence_chars") != metadata.get("evidence_chars"):
        raise SystemExit(f"{label} should expose evidence length only: {data}")
    for key in [
        "privacy_receipt_id",
        "supplied_privacy_receipt_id",
        "confirmation_receipt_nonce",
        "supplied_confirmation_receipt_id",
        "supplied_confirmation_receipt_nonce",
        "transcript_sha256",
        "voice_command_intake_contract_sha256",
        "voice_command_intake_contract_privacy_receipt_id",
        "voice_command_intake_contract_confirmation_receipt_id",
        "voice_command_intake_contract_confirmation_receipt_nonce",
        "voice_command_intake_contract_route_gate_state",
        "next_command",
        "next_review_start_command",
        "voice_post_run_closure_token_sha256",
        "verification_receipt_sha256",
        "execution_health_sha256",
        "execution_audit_sha256",
        "after_action_learning_sha256",
    ]:
        if metadata.get(key) != "" or (key in data and data.get(key) != ""):
            raise SystemExit(f"{label} should not echo or invent {key}: {data}")
    if data.get("closure_state") != "VOICE_POST_RUN_CLOSURE_UNAVAILABLE" or metadata.get("closure_state") != "VOICE_POST_RUN_CLOSURE_UNAVAILABLE":
        raise SystemExit(f"{label} should mark post-run closure unavailable: {data}")
    if data.get("handoff_state") != "VOICE_EXECUTION_HANDOFF_UNAVAILABLE" or metadata.get("handoff_state") != "VOICE_EXECUTION_HANDOFF_UNAVAILABLE":
        raise SystemExit(f"{label} should mark execution handoff unavailable: {data}")
    if data.get("ready_for_command_intake_packet") is not False or metadata.get("ready_for_command_intake_packet") is not False:
        raise SystemExit(f"{label} should block command-intake packets: {data}")
    if data.get("action_audit_available") is not False or metadata.get("action_audit_available") is not False:
        raise SystemExit(f"{label} should mark action audit unavailable: {data}")
    if data.get("audit_state") != "VOICE_ACTION_AUDIT_UNAVAILABLE" or metadata.get("audit_state") != "VOICE_ACTION_AUDIT_UNAVAILABLE":
        raise SystemExit(f"{label} should mark action audit unavailable state: {data}")
    if data.get("voice_command_intake_contract_runtime_bridge_state") != "VOICE_RUNTIME_BRIDGE_UNAVAILABLE":
        raise SystemExit(f"{label} should mark command-intake bridge state unavailable: {data}")
    if data.get("voice_command_intake_contract_route_proof_bundle_state") != "VOICE_ROUTE_PROOF_UNAVAILABLE":
        raise SystemExit(f"{label} should mark command-intake route proof state unavailable: {data}")
    if data.get("missing_blockers") != ["voice post-run closure unavailable"] or metadata.get("missing_blocker_count") != 1:
        raise SystemExit(f"{label} should keep a bounded missing post-run proof: {data}")
    if data.get("outputs") != {"handoff": ""}:
        raise SystemExit(f"{label} should not expose nested outputs: {data}")
    for key in [
        "receipt_nonce_required",
        "next_voice_review_requires_fresh_command_intake_contract",
        "next_review_requires_fresh_confirmation_receipt",
        "next_review_requires_fresh_receipt_nonce",
    ]:
        if data.get(key) is not True or metadata.get(key) is not True:
            raise SystemExit(f"{label} should keep {key}=True: {data}")
    for key in [
        "ready_for_next_voice_review",
        "post_run_closure_ready",
        "previous_confirmation_receipt_reusable_for_next_voice_review",
        "previous_transcript_hash_reusable_for_next_voice_review",
        "previous_handoff_reusable_for_next_voice_review",
        "voice_post_run_closure_token_present",
        "voice_post_run_closure_token_boundary_ready",
        "voice_post_run_closure_token_authorizes_action_now",
        "voice_post_run_closure_token_authorizes_model_call",
        "voice_post_run_closure_token_authorizes_tool_execution",
        "voice_post_run_closure_token_authorizes_approval",
        "voice_post_run_closure_token_authorizes_routing",
        "voice_post_run_closure_token_authorizes_transcript_mutation",
        "voice_post_run_closure_token_authorizes_personal_data_read",
        "voice_post_run_closure_token_authorizes_external_side_effect",
        "voice_post_run_closure_token_authorizes_next_voice_review",
        "voice_post_run_closure_token_authorizes_receipt_reuse",
        "voice_post_run_closure_token_reusable_for_next_voice_review",
        "handoff_ready",
        "post_run_verification_reviewed",
        "post_run_execution_health_reviewed",
        "post_run_execution_audit_reviewed",
        "after_action_learning_reviewed",
        "verification_receipt_hash_present",
        "execution_health_hash_present",
        "execution_audit_hash_present",
        "after_action_learning_hash_present",
        "post_run_artifact_hashes_present",
        "audit_ready_for_operator_review",
        "ready_for_command_intake",
        "action_allowed_now",
        "executable_tool_action_emitted",
        "can_emit_executable_tool_action",
        "can_auto_execute_now",
        "approval_required_after_command_intake",
        "hash_match",
        "receipt_id_match",
        "receipt_nonce_match",
        "receipt_freshness_match",
        "privacy_receipt_match",
        "voice_command_intake_contract_present",
        "voice_command_intake_contract_ready",
        "voice_command_intake_contract_authorizes_action_now",
        "voice_command_intake_contract_authorizes_model_call",
        "voice_command_intake_contract_authorizes_tool_execution",
        "voice_command_intake_contract_authorizes_approval",
        "voice_command_intake_contract_authorizes_routing",
        "voice_command_intake_contract_authorizes_transcript_mutation",
        "voice_command_intake_contract_authorizes_personal_data_read",
        "voice_command_intake_contract_authorizes_external_side_effect",
        "voice_command_intake_contract_reusable_for_next_voice_review",
        "calls_model",
        "calls_chat_model",
        "speaks_audio",
        "records_audio",
        "starts_listener",
        "requests_microphone_access",
        "microphone_access_requested",
        "transcribes_audio",
        "saves_transcript",
        "executes_tools",
        "writes_memory",
        "queues_approval",
        "approval_granted",
        "authorizes_execution",
        "routes_actions",
        "external_side_effect",
        "controls_computer",
        "writes_database",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} unsafe metadata {key}: {metadata}")
        if data.get(key) is not None and data.get(key) is not False:
            raise SystemExit(f"{label} unsafe top-level {key}: {data}")
    if data.get("prior_spoken_command_proof_only") is not True or metadata.get("prior_spoken_command_proof_only") is not True:
        raise SystemExit(f"{label} should mark prior proof as proof-only: {data}")
    for key in [
        "required_commands",
        "post_run_commands",
        "voice_command_intake_contract_proof_commands",
        "proof_commands",
        "recommended_next_commands",
        "planned_actions",
        "voice_post_run_closure_token_boundary_rows",
    ]:
        if data.get(key) not in (None, []) or metadata.get(key) != []:
            raise SystemExit(f"{label} should not invent {key}: {data}")
    if data.get("post_run_artifact_hashes") != {} or metadata.get("post_run_artifact_hashes") != {}:
        raise SystemExit(f"{label} should not expose post-run artifact hashes: {data}")
    summary_text = "\n".join(str(item) for item in data.get("summary") or [])
    for expected in [
        "Voice post-run closure unavailable.",
        f"Diagnostic: {diagnostic}",
        "raw transcript, supplied proof tokens, and post-run evidence strings are not included",
        "No command-intake contract, execution handoff, action audit, post-run closure token",
        "Voice command intake remains blocked",
        "No chat model call, speech output, microphone access",
        "/api/voice-post-run-closure",
    ]:
        if expected not in summary_text:
            raise SystemExit(f"{label} summary missed {expected!r}: {data}")
    safety = str(data.get("safety") or "")
    if "read-only" not in safety.lower() or "without recording audio" not in safety:
        raise SystemExit(f"{label} missed read-only safety copy: {data}")
    payload = json.dumps(data, ensure_ascii=False)
    _assert_no_private_channel_fragments(label, payload)
    for fragment in ["가상연락처이", "비밀메시지"]:
        if fragment in payload:
            raise SystemExit(f"{label} leaked CJK/private fragment {fragment!r}: {payload}")


def _voice_post_run_closure_failure_url() -> str:
    encoded_transcript = quote("SHOULD NOT APPEAR BotFather secret message Fixture 가상연락처이 비밀메시지 +15555550123 send telegram")
    encoded_evidence = quote("SHOULD NOT APPEAR BotFather Fixture 가상연락처이 비밀메시지 +15555550123 evidence")
    return (
        "/api/voice-post-run-closure?transcript="
        + encoded_transcript
        + "&confirmed=true"
        + "&mode=browser-push-to-talk-SHOULD%20NOT%20APPEAR"
        + "&privacy_receipt_id=voice-privacy-BotFather"
        + "&receipt_id=voice-Fixture"
        + "&receipt_nonce=%2B15555550123"
        + "&verification="
        + encoded_evidence
        + "&health="
        + encoded_evidence
        + "&audit="
        + encoded_evidence
        + "&learning="
        + encoded_evidence
        + "&verification_receipt_sha256="
        + ("a" * 64)
        + "&execution_health_sha256="
        + ("b" * 64)
        + "&execution_audit_sha256="
        + ("c" * 64)
        + "&after_action_learning_sha256="
        + ("d" * 64)
    )


def _assert_voice_post_run_closure_api_fails_closed_on_tool_error() -> None:
    with TemporaryDirectory(prefix="jarvis-status-voice-post-run-closure-error-") as temp:
        runtime = make_temp_runtime(Path(temp))

        def broken_post_run_closure(_: dict) -> ToolResult:
            raise RuntimeError("SHOULD NOT APPEAR BotFather secret message Fixture 가상연락처이 비밀메시지 +15555550123")

        runtime.registry._tools["voice_post_run_closure_packet"] = Tool(
            "voice_post_run_closure_packet",
            "Controlled smoke failure.",
            RiskLevel.READ_ONLY,
            broken_post_run_closure,
            "voice",
        )
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        with _status_server_context(runtime) as base:
            data = _read_json(base + _voice_post_run_closure_failure_url())

        _assert_voice_post_run_closure_api_failure_payload(
            label="Voice post-run closure API failure path",
            data=data,
            runtime=runtime,
            approvals_before=approvals_before,
            diagnostic="RuntimeError",
        )


