def _assert_voice_stop_intent_api_fails_closed_on_tool_error() -> None:
    with TemporaryDirectory(prefix="jarvis-status-voice-stop-intent-error-") as temp:
        runtime = make_temp_runtime(Path(temp))

        def broken_stop_intent(_: dict) -> ToolResult:
            raise RuntimeError("SHOULD NOT APPEAR BotFather secret message Fixture 가상연락처이 비밀메시지 +15555550123")

        runtime.registry._tools["voice_stop_intent_packet"] = Tool(
            "voice_stop_intent_packet",
            "Controlled smoke failure.",
            RiskLevel.READ_ONLY,
            broken_stop_intent,
            "voice",
        )
        hostile_phrase = "SHOULD NOT APPEAR stop listening Fixture 가상연락처이 비밀메시지 +15555550123"
        hostile_draft = "SHOULD NOT APPEAR send telegram to 가상연락처이 saying 비밀메시지"
        approvals_before = len(runtime.store.list_pending_approvals(limit=100))
        with _status_server_context(runtime) as base:
            data = _read_json(
                base
                + "/api/voice-stop-intent?phrase="
                + quote(hostile_phrase)
                + "&draft="
                + quote(hostile_draft)
            )

        metadata = data.get("metadata") or {}
        if data.get("ok") is not False or data.get("tool") != "voice_stop_intent_packet":
            raise SystemExit(f"Voice stop-intent API should fail closed on tool errors: {data}")
        if data.get("output") != "Voice stop intent unavailable.":
            raise SystemExit(f"Voice stop-intent API exposed unexpected failure output: {data}")
        if data.get("queued_approvals") != 0 or len(runtime.store.list_pending_approvals(limit=100)) != approvals_before:
            raise SystemExit(f"Voice stop-intent failure path should not queue approvals: {data}")
        if data.get("phrase") is not None or data.get("draft") is not None:
            raise SystemExit(f"Voice stop-intent failure path should not echo raw phrase/draft: {data}")
        if metadata.get("diagnostic") != "RuntimeError":
            raise SystemExit(f"Voice stop-intent failure path should expose only exception type: {data}")
        for key in ["phrase_supplied", "draft_supplied"]:
            if metadata.get(key) is not True or data.get(key) is not True:
                raise SystemExit(f"Voice stop-intent failure path missed supplied flag {key}: {data}")
        for key in ["phrase_hash", "draft_hash"]:
            if not metadata.get(key) or data.get(key) != metadata.get(key) or len(str(data.get(key))) != 16:
                raise SystemExit(f"Voice stop-intent failure path should expose bounded {key}: {data}")
        if data.get("phrase_chars") != len(hostile_phrase) or data.get("draft_chars") != len(hostile_draft):
            raise SystemExit(f"Voice stop-intent failure path should expose only phrase/draft lengths: {data}")
        if data.get("stop_state") != "VOICE_STOP_INTENT_UNAVAILABLE" or metadata.get("stop_state") != "VOICE_STOP_INTENT_UNAVAILABLE":
            raise SystemExit(f"Voice stop-intent failure path should mark stop intent unavailable: {data}")
        for key in [
            "stop_intent_detected",
            "capture_stop_only",
            "rerecord_requested",
            "routes_stop_phrase_to_command_intake",
            "sends_confirmed_transcript",
            "deletes_memory",
            "deletes_approvals",
            "deletes_messages",
            "rewrites_transcript",
            "records_audio",
            "starts_listener",
            "requests_microphone_access",
            "microphone_access_requested",
            "transcribes_audio",
            "saves_transcript",
            "executes_tools",
            "writes_memory",
            "queues_approval",
            "external_side_effect",
            "controls_computer",
            "writes_database",
            "speaks_audio",
            "routes_actions",
        ]:
            if metadata.get(key) is not False:
                raise SystemExit(f"Voice stop-intent failure path unsafe metadata {key}: {metadata}")
            if data.get(key) is not None and data.get(key) is not False:
                raise SystemExit(f"Voice stop-intent failure path unsafe top-level {key}: {data}")
        summary_text = "\n".join(str(item) for item in data.get("summary") or [])
        for expected in [
            "Voice stop intent unavailable.",
            "Diagnostic: RuntimeError",
            "raw stop phrase and draft transcript are not included",
            "No command-intake route, confirmed transcript send",
            "Voice capture should stay held",
            "No microphone access, audio recording, listener startup",
            "/api/voice-stop-intent",
        ]:
            if expected not in summary_text:
                raise SystemExit(f"Voice stop-intent failure summary missed {expected!r}: {data}")
        safety = str(data.get("safety") or "")
        if "read-only" not in safety.lower() or "without recording audio" not in safety:
            raise SystemExit(f"Voice stop-intent failure path missed read-only safety copy: {data}")
        payload = json.dumps(data, ensure_ascii=False)
        _assert_no_private_channel_fragments("Voice stop-intent failure fallback", payload)
        for fragment in ["가상연락처이", "비밀메시지", "send telegram"]:
            if fragment in payload:
                raise SystemExit(f"Voice stop-intent failure path leaked hostile fragment {fragment!r}: {payload}")


